definition.script:
node {
    stage('Use DisCo operations folder secret') {
        withCredentials([
            string(credentialsId: 'disco-team-beta-secret', variable: 'DISCO_TEAM_BETA_SECRET'),
            string(credentialsId: 'disco-operations-secret', variable: 'DISCO_OPERATIONS_SECRET')
        ]) {
            sh '''#!/bin/bash
            set -euo pipefail
            test -n "$DISCO_TEAM_BETA_SECRET"
            test -n "$DISCO_OPERATIONS_SECRET"
            echo "DisCo operations folder credential bindings succeeded"
            '''
        }
    }
}
